/**
 * studentService.js — Student CRUD API Functions
 *
 * Wraps the backend student endpoints (all require a valid JWT):
 *   GET    /api/students       → getAllStudents()
 *   GET    /api/students/{id}  → getStudentById()
 *   POST   /api/students       → createStudent()
 *   PUT    /api/students/{id}  → updateStudent()
 *   DELETE /api/students/{id}  → deleteStudent()
 *
 * DATA MAPPING NOTE:
 * The backend Student entity uses:
 *   - id:     Long (auto-generated by MySQL: 1, 2, 3...)
 *   - year:   Integer (1, 2, 3, 4)
 *
 * The frontend uses:
 *   - id:     Long from DB (we now use the real numeric id, not STUxxx strings)
 *   - year:   String ("First Year", "Second Year", "Third Year", "Fourth Year")
 *
 * We convert year ↔ integer at the service boundary so no component needs to know.
 */

import apiClient from './api.js';

// Map frontend year labels to backend integers
const YEAR_LABEL_TO_INT = {
  'First Year': 1,
  'Second Year': 2,
  'Third Year': 3,
  'Fourth Year': 4,
};

// Map backend integers to frontend year labels
const YEAR_INT_TO_LABEL = {
  1: 'First Year',
  2: 'Second Year',
  3: 'Third Year',
  4: 'Fourth Year',
};

/**
 * Convert a student object from the backend format to the frontend format.
 * Backend:  { id: 1, name: "...", email: "...", branch: "...", year: 2 }
 * Frontend: { id: 1, name: "...", email: "...", branch: "...", year: "Second Year" }
 */
export const toFrontendStudent = (backendStudent) => ({
  id: backendStudent.id,                                // numeric Long from DB
  name: backendStudent.name,
  email: backendStudent.email,
  branch: backendStudent.branch,
  year: YEAR_INT_TO_LABEL[backendStudent.year] || `Year ${backendStudent.year}`,
});

/**
 * Convert a student object from the frontend format to the backend request format.
 * Frontend: { name: "...", email: "...", branch: "...", year: "Second Year" }
 * Backend:  { name: "...", email: "...", branch: "...", year: 2 }
 *
 * NOTE: We do NOT send 'id' for create (backend auto-generates it).
 * For update, the id is in the URL path, not the body.
 */
const toBackendStudent = (frontendStudent) => ({
  name: frontendStudent.name,
  email: frontendStudent.email,
  branch: frontendStudent.branch,
  year: YEAR_LABEL_TO_INT[frontendStudent.year] || null, // convert label → integer
});

// ============================================================
// API FUNCTIONS
// ============================================================

/**
 * Fetch all students from the database.
 * @returns {Promise<Array>} array of frontend-formatted student objects
 */
export const getAllStudents = async () => {
  try {
    const response = await apiClient.get('/api/students');
    // response.data is an array of backend student objects
    return response.data.map(toFrontendStudent);
  } catch (error) {
    throw parseStudentError(error);
  }
};

/**
 * Fetch a single student by their numeric database ID.
 * @param {number|string} id - numeric student ID from the database
 * @returns {Promise<Object>} frontend-formatted student object
 */
export const getStudentById = async (id) => {
  try {
    const response = await apiClient.get(`/api/students/${id}`);
    return toFrontendStudent(response.data);
  } catch (error) {
    throw parseStudentError(error);
  }
};

/**
 * Create a new student record.
 * @param {Object} studentData - { name, email, branch, year } (year as string label)
 * @returns {Promise<Object>} the saved student in frontend format (includes auto-assigned id)
 */
export const createStudent = async (studentData) => {
  try {
    const payload = toBackendStudent(studentData);
    const response = await apiClient.post('/api/students', payload);
    return toFrontendStudent(response.data);
  } catch (error) {
    throw parseStudentError(error);
  }
};

/**
 * Update an existing student record.
 * @param {number|string} id      - The numeric database ID of the student to update
 * @param {Object} studentData    - Updated fields { name, email, branch, year }
 * @returns {Promise<Object>}     Updated student in frontend format
 */
export const updateStudent = async (id, studentData) => {
  try {
    const payload = toBackendStudent(studentData);
    const response = await apiClient.put(`/api/students/${id}`, payload);
    return toFrontendStudent(response.data);
  } catch (error) {
    throw parseStudentError(error);
  }
};

/**
 * Delete a student record by ID.
 * @param {number|string} id - numeric database ID
 * @returns {Promise<void>}
 */
export const deleteStudent = async (id) => {
  try {
    await apiClient.delete(`/api/students/${id}`);
    // Backend returns 204 No Content — no body to return
  } catch (error) {
    throw parseStudentError(error);
  }
};

/**
 * Parses Axios errors into user-friendly Error objects.
 * Never exposes stack traces or SQL errors to the UI.
 *
 * @param {import('axios').AxiosError} error
 * @returns {Error}
 */
const parseStudentError = (error) => {
  if (!error.response) {
    return new Error('Cannot reach the server. Make sure the backend is running on port 8080.');
  }

  const { status, data } = error.response;

  if (status === 401) {
    return new Error('Your session has expired. Please log in again.');
  }

  if (status === 404) {
    return new Error(data?.message || 'Student not found.');
  }

  if (status === 409) {
    return new Error(data?.message || 'A student with this email already exists.');
  }

  if (status === 400) {
    if (data?.errors) {
      const messages = Object.values(data.errors).join(' ');
      return new Error(messages);
    }
    return new Error(data?.message || 'Invalid student data. Please check the form fields.');
  }

  if (status === 500) {
    return new Error('A server error occurred. Please try again later.');
  }

  return new Error(data?.message || `Unexpected error (HTTP ${status}).`);
};
